Object.assign(window.LIT_VERSES,{"mutanabbi-azm-007":{"id":"mutanabbi-azm-007","poemId":"ala-qadr-ahl-al-azm","order":7,"first":"هَلِ الحَدَثُ الحَمراءُ تَعرِفُ لَونَها","second":"وَتَعلَمُ أَيُّ الساقِيَينِ الغَمائِمُ","meaning":"يخاطب المتنبي قلعة الحدث كأنها كائن واعٍ، ويسألها هل تعرف لونها بعد أن احمرت بدماء القتال، وهل تستطيع أن تميز أي ساقييها هو الغمام؛ لأن لها ساقيًا آخر سيكشفه البيت التالي: الجماجم والدماء.","vocabulary":[{"term":"الحدث","text":"ثغر وقلعة على الحدود مع الروم، ارتبطت الواقعة بإعادة بنائها في عهد سيف الدولة."},{"term":"الحمراء","text":"يشرح الشراح الحمرة بما سال في الوقعة من الدماء."},{"term":"الساقيين","text":"اثنان يسقيان القلعة في الصورة: الغمام، ثم ما يكشفه البيت التالي من الجماجم/الدماء."}],"syntax":["الاستفهام بـ«هل» موجه إلى غير عاقل في الأصل، وهو جزء من تشخيص القلعة.","في «أي الساقيين الغمائم» تأخير للمعلومة الثانية؛ لا يصرح الشاعر بالساقي المقابل داخل البيت، بل يجعل البيت التالي يجيب."],"morphology":["«الساقيين» مثنى «ساقٍ» منصوب/مجرور بالياء، وإفراد أحدهما بالذكر «الغمائم» يترك الثاني معلقًا حتى البيت التالي.","«الغمائم» جمع «غمامة»، ومقابلتها لاحقًا بـ«الجماجم» تقوم كذلك على تقارب وزني وصوتي بين جمعين، من غير أن يكون ذلك غاية الصورة.","الفعلان «تعرف» و«تعلم» مضارعان من أفعال الإدراك، وإسنادهما إلى المكان هو الذي يفتح باب التشخيص."],"rhetoric":{"thesis":"من أقوى ما في هذا الموضع أن الصورة لا تكتمل داخل البيت وحده. المتنبي يصنع سؤالًا معلقًا، ثم يجعل البيت التالي يقدّم العنصر المحذوف، فيجبر القارئ على قراءة البيتين كوحدة.","devices":[{"title":"تشخيص المكان","text":"«تعرف» و«تعلم» أفعال وعي. بإسنادهما إلى القلعة تتحول الحدث من جدار وموقع عسكري إلى شاهد حي على ما جرى فيها."},{"title":"اللون بوصفه ذاكرة","text":"السؤال «تعرف لونها» لا يصف الحمرة فقط؛ بل يوحي بأن شدة الدم بدلت هوية المكان حتى صار كأنه يراجع ذاكرته القديمة."},{"title":"الإضمار والتشويق","text":"يذكر «الغمائم» أحد الساقيين ويسكت عن الآخر. هذا النقص متعمد لأن «الجماجم» ستأتي في البيت التالي، فينشأ تعليق بين بيتين لا يجوز شرحهما منفصلين."},{"title":"الاستفهام لا طلب الجواب","text":"القلعة لن تجيب. وظيفة السؤال إثارة المشهد وإدخال القارئ فيه، لا تحصيل معلومة مجهولة. لذلك هو أداة تصوير وحجاج معًا."}],"connection":"البيت الثامن يحل السؤال: كان الغمام يسقي القلعة قبل مجيء سيف الدولة، فلما دنا صار لها سقي آخر هو الدم الذي تمثله الجماجم."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"وقفة الاستفهام في منتصف اللوحة تغير النبرة من التقرير إلى المخاطبة، فتنعش الإيقاع السردي للقصيدة قبل جواب البيت التالي."},"context":"بداية لوحة «الحدث الحمراء»، وهي انتقال من أثر الحرب في الطير إلى المكان الذي وقعت فيه الحرب نفسها.","sourceIds":["wahidi-274","ibn-aliflili-483","barquqi-162-170"]},"mutanabbi-azm-008":{"id":"mutanabbi-azm-008","poemId":"ala-qadr-ahl-al-azm","order":8,"first":"سَقَتها الغَمامُ الغُرُّ قَبلَ نُزولِهِ","second":"فَلَمّا دَنا مِنها سَقَتها الجَماجِمُ","meaning":"قبل نزول سيف الدولة بالحدث كانت الغيوم تسقيها بالمطر، فلما اقترب ووقعت المعركة صار الدم المسفوك من القتلى بمنزلة سقي آخر. يجعل المتنبي «الجماجم» هي الساقي ليكثف فظاعة المشهد وكثرة القتل.","vocabulary":[{"term":"الغمام الغر","text":"السحب البيض أو المشرقة، واللفظة تمهد لمفارقة ما يقابلها من دماء الحرب."},{"term":"نزوله","text":"نزول سيف الدولة بالموضع، لا نزول المطر؛ والضمير يعود إلى سيف الدولة في سياق الشراح."},{"term":"الجماجم","text":"رؤوس القتلى؛ وجعلها الشاعر ساقية كناية تصويرية عن كثرة الدم المسفوك في الوقعة."}],"syntax":["الشطران مبنيان على الفعل نفسه «سقتها»، مع فاعلين مختلفين: الغمام ثم الجماجم.","«قبل نزوله / فلما دنا منها» يبني تقابلًا زمنيًا واضحًا: قبل حضور سيف الدولة وبعد اقترابه."],"morphology":["«الغُرّ» جمع «أغرّ/غراء» بحسب الموصوف، ودلالته البياض أو الإشراق؛ ولذلك يحمل لونًا مضادًا للحمرة الدموية التي تحيط بالمشهد.","«الجماجم» جمع «جمجمة»، وجاء الجمع ليجعل ما يفترض أنه بقايا أفراد كتلةً مشهدية تقوم مقام الساقي الثاني.","تكرار «سقتها» بصيغة الماضي مع اختلاف الفاعل يثبت الصيغة ويبدل مادتها: ماء الغمام أولًا، ثم الدم الذي تدل عليه الجماجم."],"rhetoric":{"thesis":"هذا البيت جواب فني عن سؤال البيت السابق، ويقوم على تحويل فعل طبيعي رحيم — سقي الغمام — إلى صورة حرب دموية تحتفظ بالفعل نفسه وتبدل الفاعل.","devices":[{"title":"تكرار الفعل وتبديل الفاعل","text":"«سقتها... سقتها» يثبت الفعل نفسه، لكن «الغمام» يتحول إلى «الجماجم». من هذا التبديل وحده ينشأ الصدام بين الطبيعة والحرب."},{"title":"تقابل زمني","text":"«قبل نزوله» في مقابل «فلما دنا منها». وصول سيف الدولة هو نقطة التحول التي تنقسم عندها صورة المكان إلى ما قبل المعركة وما بعدها."},{"title":"صورة السقي الدامي","text":"السقي في الأصل إحياء بالماء، لكن الشاعر يجعله هنا بالدم. هذه المفارقة تغير القيمة الشعورية للفعل دون أن تغير لفظه، فيصبح أكثر قسوة وأشد بقاء في الذاكرة."},{"title":"البيت لا يعمل وحده","text":"«الجماجم» هي العنصر الذي أخفاه البيت السابع عند قوله «أي الساقيين الغمائم». لذلك التحليل الصحيح هنا بنيوي: البيت الثامن يكمل نحويًا وتخييلًا سؤالًا بدأ قبله."}],"connection":"بعد هذه الصورة سيواصل المتنبي وصف بناء القلعة وسط اصطدام الرماح، وينقل «المنايا» إلى صورة موج متلاطم؛ أي إن المشهد يتسع من السقي واللون إلى حركة المعركة كلها."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"التوازي بين الشطرين يرسخ المقابلة، بينما الفاء في «فلما» تسرّع التحول من الزمن الهادئ إلى زمن القتال."},"context":"جواب مباشر عن سؤال البيت السابع، وخاتمة العينة التحليلية الحالية قبل الانتقال في القصيدة إلى صورة البناء والرماح والمنايا.","sourceIds":["wahidi-274","ibn-aliflili-483","barquqi-162-170"]}});